sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

   var returnArr = []; // cria uma variavel e instancia o array 

   var grMedia = new GlideRecord("x_357506_netflix_media");
   grMedia.query(); //consulta a media e a cada media retorna um titulo, ano e nota
   while(grMedia.next()) {
		var MovieObj= {
			"title": grMedia.getValue("title"),
			"release_year": grMedia.getValue("release_year"),
			"average_rating": grMedia.getValue("average_garde"),
			"reviews" : []
	};

	var grReview = new GlideRecord("x_357506_netflix_review");
	grReview.addQuery("media",grMedia.getValue("sys_id")); // Roda somente a que adicionou
	grReview.query(); // Select * from Table
	while(grReview.next()){
		MovieObj["reviews"].push({
			"number":grReview.getValue("number"),
			"rating" : grReview.getValue("rating"),
			"description" : grReview.getValue("description"),
			"creator" :grReview.opened_by.name.toString()
		});
	}
		returnArr.push(MovieObj);

   }
return returnArr;
})(request, response);
